  460: def proc_start_ticks(pid: int) -> int | None:
  461:     """Cross-platform process creation token used to reject PID reuse."""
  462:     if os.name == "nt":
  463:         query = 0x1000  # PROCESS_QUERY_LIMITED_INFORMATION
  464:         handle = ctypes.windll.kernel32.OpenProcess(query, False, int(pid))
  465:         if not handle:
  466:             return None
  467:         try:
  468:             creation = wintypes.FILETIME()
  469:             exit_time = wintypes.FILETIME()
  470:             kernel = wintypes.FILETIME()
  471:             user = wintypes.FILETIME()
  472:             if not ctypes.windll.kernel32.GetProcessTimes(
  473:                     handle, ctypes.byref(creation), ctypes.byref(exit_time),
  474:                     ctypes.byref(kernel), ctypes.byref(user)):
  475:                 return None
  476:             return (int(creation.dwHighDateTime) << 32) | int(creation.dwLowDateTime)
  477:         finally:
  478:             ctypes.windll.kernel32.CloseHandle(handle)
  479:     try:
  480:         fields = Path("/proc/%d/stat" % pid).read_text(encoding="ascii").split()
  481:         return int(fields[21])
  482:     except (OSError, ValueError, IndexError):
  483:         return None
